package com.lacoste.verification; import java.util.regex.*; public final class SmsParser { public static String provider(String t){if(t==null)return null;if(Pattern.compile("\\bConfirmado\\s+[A-Z0-9.]+",2).matcher(t).find())return "vodacom";if(Pattern.compile("ID\\s+da\\s+transacao\\s+[A-Z0-9.]+",2).matcher(t).find())return "emola";return null;} public static String id(String t){if(t==null)return "";Matcher m=Pattern.compile("ID\\s+da\\s+transacao\\s+([A-Z0-9.]+)",2).matcher(t);if(m.find())return m.group(1).replaceAll("[.]$","");m=Pattern.compile("Confirmado\\s+([A-Z0-9.]+)",2).matcher(t);return m.find()?m.group(1).replaceAll("[.]$",""):"";} public static double value(String t){if(t==null)return -1;Matcher m=Pattern.compile("transferiste\\s*([0-9]+(?:[.,][0-9]+)?)\\s*mt",2).matcher(t);if(!m.find())return -1;try{return Double.parseDouble(m.group(1).replace(',','.'));}catch(Exception e){return -1;}}}
